      creativity_rigor_blurb2: 'Кожен рівень CodeCombat створено на основі мільйонів навчальних сесій і оптимізовано для адаптації під потреби учня. Тренувальні рівні та підказки допомагають подолати труднощі, а контрольні завдання перевіряють засвоєння матеріалу.',
