      codecombat_home_blurb: '__codecombatHome__ пропонує вашій дитині цікавий і захопливий спосіб покращення навичок програмування. З доступом до понад 530 рівнів та ексклюзивними функціями такими як вихованці, предмети лише для преміум-користувачів та герої, ваша дитина може повністю зануритись у світ програмування. Вони можуть навіть розробляти ігри для виклику друзів, створювати веб-сайти та додатки для обміну, і створювати приватні команди для змагань на загальнодоступній турнірній таблиці, все в безпечному та інтерактивному середовищі, яке заохочує навчання та соціалізацію.',
