      for_libraries_title: 'Інтеграція бібліотеки',
      for_libraries_blurb: 'Як повністю саморегульований і самокерований цифровий ресурс, CodeCombat є найкращою інтеграцією для бібліотек, які хочуть дати своїм членам всіх вікових категорій можливість навчитися програмувати. Наша платформа пропонує все, що потрібно учням, щоб отримати високоякісну освіту з програмування через унікально захопливий, ігровий навчальний план. Ідеально підходить для учнів з третього класу й до дорослих, які хочуть освоїти поняття програми коледжів.',
