      path_success: 'Ігрова платформа відповідає звичайній навчальній програмі з інформатики, тому, проходячи рівні гри, студенти виконують курс. Учні вчаться програмуванню та інформатиці, граючи, а потім використовують ці навички в арені битв, практикуючись і граючи на одній платформі.',
