      season11_announcement_1: 'Змагання стає все напруженішим! Коли сонце світить згори, встановлюй та покращуй свої сонячні панелі, уникай електричних пасток, розміщуй роботизованих крабів і проходь через портали, отримуй якомога більше сонячної енергії і здобувай перемогу!',
      season10_announcement_1: 'Це вогняно гаряче, і магмові валуни випромінюють потужну енергію! Викликайте одиниці та використовуйте заклинання, щоб штовхати магмові валуни на територію вашого супротивника. Пристосовуйтеся до постійно змінюваної гравітації на полі бою!',
