      season8_announcement_1: 'Це сезон збирання врожаю у Farmscape Blitz, Сезон 8! Коли листя псується, час кодувати свій шлях серед диких і непрохідних перешкод на фермі. Стратегічно збирайте важливі підсилення, щоб покращити вашу робот-працівника, та використовуйте спеціальні здібності, щоб підвищити продуктивність і переграти своїх суперників!',
