      ai_support_acceleration_text: 'Ми використовуємо ШІ, щоб зробити час навчання більш ефективним. CodeCombat тепер підтримує функцію підказок ШІ, яка оцінює код, вказує на помилки та пояснює, як їх виправити. Найважливіше те, що вона надає весь контекст, необхідний для розуміння "чому", без розкриття всього рішення. Учням все одно доведеться вирішувати кодувальні завдання на кожному рівні, але тепер вам не потрібно переривати заняття, щоб задовольнити індивідуальні потреби. **Вчителі отримують 100 підказок ШІ на день**, а **кожен учень отримує 5 підказок ШІ на день**, щоб гарантувати постійну підтримку.',
      codecombat_ai_hackstack_text: 'Для тих, хто новачок в AI, ми пропонуємо **CodeCombat AI HackStack**. Цей інноваційний інструмент не тільки навчає студентів користуватися AI, але й надає безпечний доступ до багатьох новітніх LLM, включаючи ChatGPT-4, Claude, Stable Diffusion, DALL-E та інших. Лише після невеликого часу роботи в навчальному режимі, користувачі відкривають повний творчий потенціал інструмента, дозволяючи створювати проекти від запиту до опублікованого результату за кілька хвилин. Цей застосунок на основі AI дозволяє користувачам створювати ігри, мистецтво, вебсайти, код тощо. **Вчителі отримують 100 AI-запитів на місяць**, а **кожен студент одержує 10 AI-запитів на тиждень**, щоб створювати декілька AI проектів.',
