      testimonials_1_title: "Вчитель комп'ютерної науки AP, Старша школа Лейк Брантлі. Переможець премії Білий Дім - Чемпіон Змін",
      testimonials_2_name: 'Таннер Гігін',
      testimonials_2_title: 'Редактор з навчального матеріалу, Common Sense Education',
      testimonials_2_full_review_text: 'Повний огляд тут',
      testimonials_3_name: 'Стів Конг',
      testimonials_3_title: 'Спеціаліст з навчальних послуг, об’єднаний шкільний округ Ріверсайд',
      testimonials_4_title: 'Учень середньої школи “Гірський хребет”',
      testimonials_5_name: 'Сандра Олстром',
      testimonials_5_title: 'Вчитель, Шкільний округ Шерідан #2',
      faq_1_question: 'Що потрібно знати про сертифікаційні іспити та AP CSP',
      faq_2_question: 'Як ми використовуємо штучний інтелект для підтримки педагогів',
      faq_2_answer: 'Ми використовуємо ШІ, щоб зробити час навчання більш ефективним. Зі збільшенням розмірів класу та обмеженим часом на індивідуальне навчання наш помічник з рівневим чатом на базі ШІ - ідеальний інструмент для задоволення індивідуальних запитань учнів. Цей потужний помічник може оцінювати код, вказувати на помилки, пояснювати, як їх виправити, і надавати весь контекст "чому". І головне, він не даватиме розв’язання. Учням усе ще потрібно буде працювати над завданням на кожному рівні, але тепер вам не потрібно переривати заняття для задоволення індивідуальних потреб.',
      faq_3_question: 'Як ми інтегруємо штучний інтелект безпечно та відповідально',
      faq_3_answer: 'Наша технологія ШІ дотримується принципів безпеки в першу чергу, надаючи впевненість як студентам, так і педагогам. Ми не дозволяємо нашим постачальникам LLM використовувати ваші чати для навчання та встановили захисні заходи проти невідповідного контенту. Ці заходи включають фільтрацію шкідливої мови, збереження фокусу на актуальних темах, захист особистої інформації та навчання студентів про потенційні небезпеки ШІ. Крім того, ми реєструємо активність чатів ШІ для моніторингу вчителями та дотримуємося суворих протоколів конфіденційності та безпеки даних.',
      faq_4_question: "Чому комп'ютерні науки важливі",
      faq_4_answer: "Освіта в галузі комп'ютерних наук надає негайні переваги в поліпшенні компетенцій з розв'язання проблем, загостренні математичних навичок, та заохочує логічне мислення, необхідне для успіху в інших основних шкільних предметах. Навчання виходить далеко за межі коду, підвищуючи здатність студентів вирішувати складні проблеми і адаптуватися до різних ситуацій. Дізнайтеся, як Ozaria допомагає зробити ці **[https://docs.google.com/presentation/d/1xcc1tw4k8oY9basXuxO0v_RU9z-Dr8ImvbvbuNvJeHA/edit#slide=id.g134a7e7c8f1_0_3]міжпредметні зв'язки**. Наша навчальна програма розроблена для того, щоб сьогоднішні студенти отримали важливі навички в галузі комп'ютерних наук, які приготують їх до цифрових професій майбутнього.",
      faq_5_question: 'Чому навчання через ігри працює',
      faq_5_answer: 'Навчання на основі ігор настільки ефективне, тому що воно надає безпечне середовище, де невдачі не викликають страху, а очікувані як можливість для зростання і розуміння. Цей підхід заохочує учнів вчитися на своїх помилках і адаптувати свою стратегію для успіху. Крім того, інтерактивний та динамічний характер ігор допомагає учням зберігати інформацію більш ефективно, адже вони навчаються через практичний, активний досвід. Це активно залучає учнів до процесу навчання, підвищуючи їх мотивацію та задоволення.',
      faq_7_question: 'Як розпочати',
      faq_7_answer_1: 'Створи свій обліковий запис Учителя або Адміністратора',
      faq_7_answer_2: 'Створи клас',
      faq_7_answer_3: 'Додай учнів',
      faq_7_answer_4: 'Сядь і подивися, як твої учні весело вчаться кодувати',
      faq_8_question: 'Підтримка входу через Clever та Google',
      faq_9_question: 'Рекомендований браузер та операційна система',
      faq_9_answer: 'CodeCombat та Ozaria найкраще працюють на комп’ютерах з не менше ніж 4GB оперативної пам’яті, в сучасному браузері, такому як Chrome, Safari, Firefox або Edge. На хромбуках з 2GB оперативної пам’яті можуть бути незначні графічні проблеми на пізніших курсах. Мінімальна швидкість інтернету для студента — 200 Кбіт/с, хоча рекомендована швидкість — 1+ Мбіт/с.',
      core_curriculum_1_title: 'Клас Ozaria',
