      carousel_1_text: "**[https://csteachers.org/k12standards/]Computer Science Teachers Association K-12 Computer Science Standards** встановлюють основний набір навчальних цілей, які забезпечують основу для повної навчальної програми комп'ютерних наук і її реалізації в K-12. [NEWLINE]CodeCombat визнано CSTA як затверджений постачальник навчальних програм та професійного розвитку. Навчіться ефективно викладати інформатику за допомогою нашого самонавчального курсу **[https://www.ozaria.com/professional-development]Professional Development**, акредитованого CSTA. Отримайте до 40 кредитних годин без прив'язки до часу та пристрою. [NEWLINE]Дізнатися про детальну відповідність CSTA стандартам можна нижче:",
