      carousel_2_title: "Принципи комп'ютерної науки AP (AP CSP)",
      carousel_2_text: 'CodeCombat визнаний College Board як рекомендований постачальник навчальної програми і професійного розвитку для AP® Computer Science Principles (AP CSP). Це визнання підтверджує, що навчальна програма CodeCombat відповідає всім стандартам AP Curriculum Framework і оцінюванню AP CSP. Це надає школам доступ до ресурсів, включаючи AP CSP навчальний план, заздалегідь затверджений Course Audit College Board, і офіційно визнаний професійний розвиток, який готує вчителів до викладання цієї програми. [NEWLINE] Дізнайтеся більше про нашу програму CodeCombat AP CSP нижче:',
      carousel_2_button_1_text: 'CodeCombat AP CSP',
      carousel_3_title: 'Міжнародне товариство з технологій в освіті (ISTE)',
      carousel_3_text: 'Зосереджені на педагогіці, а не на інструментах, **[https://iste.org/standards] стандарти ISTE** є каркасом для використання технологій в освіті. [NEWLINE]Курси CodeCombat відповідають всім стандартам ISTE для учнів та вчителів.[NEWLINE]Дізнайтеся про детальну відповідність стандартам ISTE нижче:',
