      core_curriculum_title_21: 'Спікер з UC Berkeley',
      core_curriculum_title_22: 'Google X - Виступ Основного Спікера з "Фабрики Місяця"',
      core_curriculum_text_22: 'У 2010 році засновники Google Ларрі Пейдж і Сергій Брін вирішили створити новий підрозділ компанії для роботи над "місячними пострілами": дивовижними, фантастичними технологіями, які одного дня можуть зробити світ набагато кращим. За 10 років X інкубував сотні різних проектів, багато з яких стали незалежними бізнесами. Послухай, як ця різноманітна група винахідників і підприємців створює та запускає технології, що покращують життя мільйонів, а то й мільярдів людей.',
      core_curriculum_title_23: 'Нік Вінтер, генеральний директор, CodeCombat',
      core_curriculum_text_23: "Нік є засновником та генеральним директором CodeCombat. Досвідчений лідер в edtech-індустрії, Нік поєднує пристрасть до освіти з технологічною експертизою, щоб зробити навчання програмування доступнішим та захоплюючим для студентів по всьому світі. До CodeCombat він співзаснував Skritter, платформу для вивчення китайських та японських ієрогліфів. Зі сильним зобов'язанням до революціонізації освітнього сектора, Нік активно працює над тим, щоб зробити кодування фундаментальною навичкою для майбутнього покоління. Його відданість та бачення продовжують надихати та впливати на галузь edtech.",
      core_curriculum_title_24: 'Майстер-клас з розвитку технологій Apple',
      core_curriculum_text_24: 'Почуйте з перших вуст від команди венчурних капіталістів і технічних лідерів, як вони детально описують процес створення глобальної технічної платформи та створення успішного бізнес-плану. Ця інтерактивна презентація розкриє завісу над тим, як створити наступний великий шматок техніки і як його запустити.',
      core_curriculum_heading_31: 'Сан-Франциско та Силіконова долина пропонують студентам унікальну можливість  ',
      core_curriculum_heading_33: 'і ',
      core_curriculum_title_31: 'Відвідати Google HQ і X- The Moonshot Factory',
      core_curriculum_text_31: 'Розташований у Маунтін-В’ю, Каліфорнія, кампус Google пропонує унікальний погляд у серце інновацій Силіконової долини. Студенти побачать казкову архітектуру, безліч спільних робочих просторів і арт-інсталяцій, що надихають творчість і розкривають, якою може бути робота в техногалузі. Цей ексклюзивний тур відвідає X - The Moonshot Factory, щоб побачити, як ця інноваційна команда всередині Google створює радикально нові технології, щоб вирішити деякі з найскладніших проблем світу.',
      core_curriculum_title_32: 'Візит до Apple Park HQ та Майстер-клас',
      core_curriculum_text_32: 'Apple Park є глобальною штаб-квартирою для інноваційного техгіганта і обов\'язковим місцем для відвідування в Сан-Франциско. Студенти відчують "Гаражну культуру" Стіва Джобса, яка надихнула Apple стати найбільшою компанією у світі, і приєднаються до майстер-класу з венчурними капіталістами та лідерами технологій, щоб з перших вуст дізнатися, що потрібно, щоб створити глобальну техноплатформу та розробити власний бізнес-план.',
      core_curriculum_title_33: 'Тур Сан-Франциско',
      core_curriculum_text_33: 'Учні мають можливість зануритися в різноманітний і динамічний шарм Сан-Франциско. Від іконічного Золотого мосту та історичного острова Алькатрас до жвавої гавані та спокійних парків - пригоди на кожному кроці. Візит до Сан-Франциско — це захопливе поєднання природної краси, міського витонченості та багатої культурної спадщини, що обіцяє незабутні враження.',
      cta_supporting: "Деталі запланованої серії заходів можуть змінюватися. Ми зобов'язуємося інформувати тебе про такі зміни настільки, наскільки це можливо, хоча вони можуть відбутися без попередження.",
