      accessibility_text_4: "На цей час немає обмежень на подорожі через Covid або іншу хворобу. Якщо обмеження на подорожі буде відновлено або якщо наша команда вважатиме, що є загроза для здоров'я учасників, досвід може бути змінено або скасовано.",
      faq: 'Поширені запитання',
      faq_q_1: 'Чи є вікові обмеження?',
      faq_a_1: 'Учасниками повинні бути особи віком 13-17 років та мати можливість надати легальні документи для поїздки.',
