      "HowItWorksPage_but-i-dont-have-accounts-for-those-and-i": 'але у мене немає облікових записів для цього, і я думаю, що chatgpt тут заблокований',
      "HowItWorksPage_but-who-made-you": 'але хто тебе створив?',
      "HowItWorksPage_codecombat-ai-hackstack-is-an-all-in-one": 'CodeCombat AI HackStack — універсальний AI-інструмент для створення ігор, мистецтва, пісень, додатків і багато іншого просто за допомогою чату. Він запускає все за вас, хостить ваші проекти і допомагає з кодуванням. CORE режим безкоштовний і навчає вас за допомогою різноманітних запитань з варіантами відповідей. PRO+ режим — це $9.99/міс для вільних підказок. Проекти безпечні і не передають дані великим технологічним компаніям. Він створений командою CodeCombat, щоб зробити AI доступним для всіх. А тепер давайте почнемо створювати.',
      "HowItWorksPage_core-mode-is-free-and-you-dont-even-need": 'Режим CORE безкоштовний, і навіть не потрібен акаунт, щоб СПРОБУВАТИ! Якщо захочеш протестувати всі можливості в режимі PRO+, це коштує $9.99/міс, але ти можеш тестувати деякі можливості безкоштовно кожен день.',
      "HowItWorksPage_i-got-you-we-can-build-that-and-more": 'Я зрозумів тебе! Ми можемо побудувати це і більше.',
