      "HowItWorksPage_just-chat-and-lets-see-what-we-can-creat": 'Просто спілкуйся, і подивимось, що ми створимо разом.',
      "HowItWorksPage_just-chat-with-me-ill-show-you": 'Просто поговори зі мною, я покажу тобі.',
      "HowItWorksPage_learn-anything-create-something-do-every": 'Вивчайте ЩО ЗАВГОДНО, створюйте ЩО ЗАВГОДНО з CodeCombat AI HackStack! Можливості ШІ для кожного!',
      "HowItWorksPage_lets-go": 'ПОЇХАЛИ!!!',
      HowItWorksPage_marketing: 'Маркетинг',
      "HowItWorksPage_most-things-if-the-ai-isnt-smart-enough-": 'Майже все. Якщо штучний інтелект ще не настільки розумний для чогось, то скоро буде! Ви зможете отримати доступ до всіляких креативних проектів у нашій галереї. Ось кілька, над якими я працюю з іншими користувачами зараз: - Генератор вибору власної пригоди, що може надіслати вам фізичну книгу - Інтернет-магазин для нестандартного одягу та аксесуарів Roblox - Віртуальна гра "Екстремальний лускутник прищів". Так, деякі творці сприймають ідею “безмежної креативності” буквально!',
      "HowItWorksPage_not-with-ai-hackstack-i-access-all-the-l": 'Не з AI HackStack. Я маю доступ до всіх останніх моделей, від GPT-4 до Stable Diffusion і всього що між ними.',
      "HowItWorksPage_of-course": 'Звичайно.',
      "HowItWorksPage_oh-im-an-incredible-host-every-project-h": 'Ой, я неймовірний хост! Кожен проєкт має URL, який ти можеш поділитися зі світом. Створи вебсайт і розпочни бізнес прямо в чаті. Або завантаж свій проєкт, синхронізуй на GitHub чи візьми код і вирушай - вибір за тобою.',
      "HowItWorksPage_the-codecombat-team-they-got-really-good": 'Команда CodeCombat. Вони стали дуже добрими у тому, щоб зробити навчання складних речей легким, навчаючи 20 мільйонів початківців програмуванню через навчання в грі, і коли технологія стала достатньо хорошою, вони захотіли зробити те саме для AI. Якщо AI – це майбутнє творчості, тоді нам потрібно зробити його легким для використання!',
      "HowItWorksPage_well-start-you-off-easy-in-core-mode-wit": 'Ми почнемо з простого в режимі CORE з дуже простими запитаннями та відповідями, щоб підготувати вас до найкращого формулювання підказок. Потім ми поєднаємо ці підказки, щоб створити ваш перший проект. Протягом кількох хвилин ви будете готові до режиму PRO+, де обмеження знімаються і все можливо.',
      "HowItWorksPage_wow-dont-you-need-like-a-100-different-a": 'ОГО!!! - тобі не потрібно як 100 різних інструментів AI для цього',
      "HowItWorksPage_yeah-thats-why-those-are-free-they-feed-": 'Та ну, ось чому це безкоштовно. Вони подають твої дані у свою наступну AI, щоб вона могла навчитися створювати кращі любовні реп-битви. Але коли ти використовуєш мене, вони не зберігають або тренуються на цьому. Тож якщо ти в школі або тобі менше 18 і маєш згоду від батьків, чи менше 13 взагалі, ти технічно не можеш використовувати ChatGPT напряму. З AI HackStack ти в безпеці, захищений і готовий до роботи.',
      "HowItWorksPage_yep-im-here-to-accelerate-your-creative-": 'Так! Я тут, щоб прискорити твій творчий потенціал, зарядити твої мрії, забезпечити ракетне пальне для твоєї уяви! Ігри, музика, фільми, додатки, мистецтво, веб-сайти, коди і що завгодно інше в твоїй дивовижній голові можливо саме тут.',
      "HowItWorksPage_you-could-but-i-answer-faster-dont-rate-": 'Можеш, АЛЕ Я... - відповідаю швидше - не обмежую тебе в рейтингу - даю більше моделей ШІ - навчаю тебе, як користуватися ШІ - автоматично створюю та розміщую проекти для тебе - маю простішу, але потужнішу інтерфейс - даю вбудоване керівництво з етики, щоб ти не випадково не списав з інших - дозволяю переглядати вихідний код та реміксити проекти інших О, і я не… НЕ ВІДПРАВЛЯЮ ВСІ ВАШІ ЧАТИ В OPENAI/MICROSOFT/GOOGLE ДЛЯ НАВЧАННЯ!!!!!',
